package com.acme.billing

import jakarta.validation.Valid
import org.springframework.http.HttpStatus
import org.springframework.http.ResponseEntity
import org.springframework.security.access.prepost.PreAuthorize
import org.springframework.web.bind.annotation.*

@RestController
@RequestMapping("/api/invoices")
class InvoiceController(private val invoices: InvoiceService) {

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun issue(@Valid @RequestBody request: IssueInvoiceRequest): Invoice = invoices.issue(request)

    @PostMapping("/{id}/pay")
    @PreAuthorize("hasRole('ACCOUNTANT')")
    fun pay(@PathVariable id: String): ResponseEntity<Invoice> = ResponseEntity.ok(invoices.pay(id))

    @GetMapping("/{id}")
    fun get(@PathVariable id: String): Invoice = invoices.find(id)
}
